<template><div class="app" @keydown.esc="escape"><aside class="sidebar" :class="{'is-open':sidebarOpen}" aria-label="主导航"><div class="brand"><div class="brand-symbol"><svg viewBox="0 0 34 34" fill="none" aria-hidden="true"><path d="m4 12 13-7 13 7-13 7z" fill="currentColor"/><path d="m4 18 13 7 13-7M4 24l13 7 13-7" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"/></svg></div><div><div class="brand-cn">青山云盘</div><div class="brand-en">企业文件工作台</div></div></div><div class="new-wrap"><button class="new-button" @click="newMenu"><Icon name="plus"/><span>新建</span><span class="spare-new"><Icon name="down" class="small"/></span></button></div><div class="sidebar-middle"><nav class="nav"><RouterLink v-for="n in nav" :key="n.path" class="nav-item" :class="{active:active(n.path)}" :to="n.path"><Icon :name="n.icon"/><span>{{n.label}}</span></RouterLink></nav><section class="recent-side"><div class="side-label"><span>最近打开</span><RouterLink to="/recent" class="text-button">全部<Icon name="right" class="small"/></RouterLink></div><button class="recent-item" v-for="item in ui.recent" :key="item.id" @click="run(()=>ops.openItem(item,router))"><FileGlyph :item="item" size="mini"/><span class="recent-info"><span class="recent-name">{{item.name}}</span><span class="recent-time">{{time(item.lastAccessedAt)}}</span></span></button><p v-if="!ui.recent.length" class="tiny-note">打开文件后会显示在这里</p></section></div><div class="side-bottom"><div :title="usageHint"><div class="storage-title"><span>存储空间</span><Icon name="building"/></div><div class="storage-track" role="meter" aria-label="个人盘使用量" :aria-valuenow="usagePercent" aria-valuemin="0" aria-valuemax="100"><span :style="{width:usagePercent+'%'}"/></div><div class="storage-line"><span><strong>{{ui.usage?size(ui.usage.usedBytes):'—'}}</strong> / {{ui.usage?size(ui.usage.referenceBytes):'100 GB'}}</span><span>参考容量</span></div></div><div class="workspace-label"><Icon name="building"/><span class="truncate" :title="organization">{{organization}}</span><span class="spacer"/><Icon name="lock"/></div></div></aside><div class="sidebar-scrim" :class="{'is-open':sidebarOpen}" @click="sidebarOpen=false"/><main class="main"><header class="topbar"><button class="icon-button mobile-menu" title="打开导航" @click="sidebarOpen=true"><Icon name="menu"/></button><div class="search-box" role="search"><Icon name="search"/><input ref="searchInput" v-model="search" type="search" maxlength="100" placeholder="搜索文件、文件夹或空间" aria-label="搜索全部有权限内容" @input="scheduleSearch" @keydown.enter.prevent="submitSearch"/><button v-if="search" class="icon-button search-clear" title="清除搜索" @click="search='';submitSearch()"><Icon name="close"/></button><kbd class="keycap">Ctrl K</kbd></div><div class="top-right"><span class="top-separator"/><button class="icon-button" title="传输记录" @click="run(ops.transfers)"><Icon name="transfer"/><span v-if="busyUploads()" class="transfer-dot"/></button><button class="icon-button" title="使用说明" @click="ops.help"><Icon name="help"/></button><button class="avatar-btn" :title="personName" aria-label="账号菜单" @click="userMenu"><span class="avatar">{{personName.slice(0,1)}}</span><span class="profile-name">{{personName}}</span><Icon name="down"/></button></div></header><div class="workspace"><div class="content-scroll"><RouterView v-if="ui.ready" v-slot="{Component}"><component :is="Component" @upload="chooseUpload"/></RouterView><div v-else class="empty">正在加载云盘…</div></div><aside v-if="ui.detail" class="details" aria-label="文件详情"><header class="detail-top"><span class="detail-title"><Icon name="info"/>文件详情</span><button class="icon-button" title="关闭详情" @click="ui.detail=null"><Icon name="close"/></button></header><div class="detail-scroll"><div class="detail-preview"><div class="preview-generic"><FileGlyph :item="ui.detail" size="large"/></div></div><h2 class="detail-name">{{ui.detail.name}}</h2><p class="detail-submeta">{{ui.detail.itemType==='folder'?'文件夹':size(ui.detail.sizeBytes)}}</p><p v-if="ui.detail.loading">加载中…</p><p v-if="ui.detail.error" class="error-text">{{ui.detail.error}} <button class="text-button" @click="run(()=>ops.details(ui.detail))">重试</button></p><section class="detail-section"><h3>基本信息</h3><dl><div class="detail-kv"><dt>所在位置</dt><dd>{{ui.detail.displayPath||'—'}}</dd></div><div class="detail-kv"><dt>修改者</dt><dd>{{ui.detail.modifiedByName||'未知'}}</dd></div><div class="detail-kv"><dt>修改时间</dt><dd>{{time(ui.detail.updatedAt)}}</dd></div><div class="detail-kv"><dt>文件归属</dt><dd>{{ui.detail.source==='workspace'?'协作空间':ui.detail.ownerName}}</dd></div></dl></section><section v-if="!ui.detail.deleted" class="detail-section"><h3>访问权限</h3><div class="detail-access"><Icon name="lock"/><span>{{ui.detail.allowManage?'可以管理':ui.detail.allowEdit?'可以编辑':ui.detail.allowDownload?'可以下载':'仅预览'}}<small>{{ui.detail.source==='shared'?'通过有效共享访问':ui.detail.source==='workspace'?'按空间角色授予权限':'个人文件'}}</small></span></div></section><section v-if="ui.detail.allowVersions" class="detail-section"><h3>版本记录</h3><div class="version-row" v-for="v in ui.detail.versions" :key="v.id"><span class="version-dot"/><div>v{{v.versionNumber}}<p>{{v.personName}} · {{time(v.createdAt)}}</p><div class="version-actions"><button class="text-button" @click="run(()=>ops.openItem(ui.detail,router,false,v))">查看</button><button class="text-button" @click="downloadVersion(v)">下载</button></div></div></div><p class="tiny-note">历史版本只读，永久删除文件时一并删除。</p></section></div><footer class="drawer-share"><button class="btn primary" @click="run(()=>ui.detail.deleted?ops.restore([ui.detail]):ops.openItem(ui.detail,router))">{{ui.detail.deleted?'恢复文件':ui.detail.itemType==='folder'?'打开文件夹':'打开预览'}}</button><button v-if="ui.detail.allowManage&&!ui.detail.deleted" class="btn" @click="run(()=>ops.share([ui.detail]))">共享与权限</button></footer></aside></div><footer class="app-status"><Icon name="shield"/><span v-if="ui.error" class="error-text">{{ui.error}} <button class="text-button" @click="run(init)">重试</button></span><span v-else>青山云盘 · 企业文件工作台</span><span>安全协作</span></footer></main></div><div v-if="ui.popup" class="popup" ref="popupRef" role="menu" :style="{left:ui.popup.x+'px',top:ui.popup.y+'px'}" @keydown="popupKeys"><button v-for="(a,i) in ui.popup.actions" :key="i" class="menu-item" :class="{danger:a.danger,disabled:a.disabled}" type="button" role="menuitem" :aria-disabled="a.disabled||false" :title="a.hint||''" :data-hint="a.hint||''" @click="execute(a)"><Icon :name="a.icon"/><span>{{a.label}}</span></button></div><div v-if="ui.toast" class="toast" role="status" aria-live="polite"><Icon name="checkcircle"/><span>{{ui.toast}}</span></div></template>
<script setup>
import {computed,ref,watch,onMounted,onUnmounted,nextTick} from 'vue';import {RouterLink,RouterView,useRoute,useRouter} from 'vue-router';import Icon from './components/Icon.vue';import FileGlyph from './components/FileGlyph.vue';import {ui,init,run,dialog,busyUploads,changed} from './state';import * as ops from './operations';import * as api from './api';import {formatFileSize as size,formatTime as time} from '../utils/formatters';import {CLOUDNEXT_DRIVE_REFRESH_KEY} from '../session';
const route=useRoute(),router=useRouter(),search=ref(''),sidebarOpen=ref(false),searchInput=ref(null),popupRef=ref(null);let timer;
const personName=computed(()=>ui.session?.personName||'当前用户'),organization=computed(()=>ui.session?.displayPath||ui.session?.identityList?.[0]?.displayPath||'企业工作空间');
const usagePercent=computed(()=>ui.usage?Math.min(100,ui.usage.usedBytes/Math.max(1,ui.usage.referenceBytes)*100):0),usageHint=computed(()=>ui.usage?'个人文件 '+size(ui.usage.activeBytes)+'，回收站 '+size(ui.usage.trashBytes)+'，历史版本 '+size(ui.usage.versionBytes)+'。参考容量不限制上传。':'正在加载用量');
const nav=[{path:'/',label:'首页',icon:'home'},{path:'/my-files',label:'我的文件',icon:'file'},{path:'/shared',label:'共享文件',icon:'shared'},{path:'/workspaces',label:'协作空间',icon:'people'},{path:'/links',label:'外链管理',icon:'globe'},{path:'/trash',label:'回收站',icon:'trash'}];
const active=p=>p==='/'?route.path==='/':route.path.startsWith(p);
function submitSearch(){clearTimeout(timer);router.push({path:'/search',query:search.value.trim()?{keyword:search.value.trim()}: {}});}
function scheduleSearch(){clearTimeout(timer);timer=setTimeout(submitSearch,300);}
function chooseUpload(){if(ui.context.readOnly)return;void dialog({title:'上传文件',kind:'upload',description:'支持一次选择多个文件。目标：'+(ui.context.scopeName||'我的文件')+(ui.context.parentId?' / 当前文件夹':' / 根目录'),target:{...ui.context}});}
function newMenu(e){ops.menu(e,[{label:'新建文件夹',icon:'folder',disabled:ui.context.readOnly,hint:ui.context.readOnly?'当前空间不可写':'',run:()=>ops.createFolder()},{label:'新建文档',icon:'document',disabled:true,hint:'暂不支持该功能'},{label:'上传文件',icon:'upload',disabled:ui.context.readOnly,hint:ui.context.readOnly?'当前空间不可写':'',run:chooseUpload}]);}
function userMenu(e){ops.menu(e,[{label:personName.value,icon:'user',run:()=>dialog({title:'当前账号',description:organization.value,records:[{id:'employee',name:'工号',description:ui.session?.employeeNo||'—'},{id:'session',name:'会话有效至',description:time(ui.session?.expiresAt)}]})},{label:'我的收藏',icon:'star',run:()=>router.push('/favorites')},{label:'界面偏好',icon:'sliders',run:()=>ops.preferences(router)},{label:'使用说明',icon:'help',run:ops.help},...(ui.admin?[{label:'系统管理',icon:'building',run:()=>router.push('/admin')}]:[]),{label:'退出登录',icon:'logout',run:()=>ops.logout(router)}]);}
function execute(a){if(a.disabled)return;ui.popup=null;void run(a.run);}
function popupKeys(e){const list=[...popupRef.value.querySelectorAll('button')],at=list.indexOf(document.activeElement);if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();list[(at+(e.key==='ArrowDown'?1:list.length-1)+list.length)%list.length]?.focus();}if(e.key==='Escape')ui.popup=null;}
function outside(e){if(ui.popup&&!popupRef.value?.contains(e.target))ui.popup=null;}
function escape(){if(ui.dialogs.length||ui.preview)return;ui.popup=null;ui.detail=null;}
function keyboard(e){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!ui.dialogs.length){e.preventDefault();searchInput.value?.focus();searchInput.value?.select();}}
function storage(e){if(e.key===CLOUDNEXT_DRIVE_REFRESH_KEY){ui.revision++;}}
async function downloadVersion(v){await run(async()=>{const blob=await api.blob('/api/drive/items/'+ui.detail.id+'/versions/'+v.id+'/download');const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=v.fileName;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);});}
watch(()=>route.fullPath,()=>{sidebarOpen.value=false;ui.popup=null;search.value=route.path==='/search'?String(route.query.keyword||''):'';if(!['/my-files'].includes(route.path)&&!route.params.id)ui.context={scopeType:'PERSONAL',scopeId:'',parentId:''};});
watch(()=>ui.popup,async value=>{if(value){await nextTick();popupRef.value?.querySelector('button')?.focus();}});
onMounted(()=>{void run(init);window.addEventListener('pointerdown',outside);window.addEventListener('keydown',keyboard);window.addEventListener('storage',storage);});
onUnmounted(()=>{clearTimeout(timer);window.removeEventListener('pointerdown',outside);window.removeEventListener('keydown',keyboard);window.removeEventListener('storage',storage);});
</script>
